import{z as l,x as p,o as s,c as A,q as n,j as o,D as E,d as e,s as B,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"IP 分片","description":"","frontmatter":{"title":"IP 分片","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ip-fragment.md","filePath":"cs/ip-fragment.md","lastUpdated":1791063341000}'),d={name:"cs/ip-fragment.md"};function D(P,a,m,f,T,c){const r=p("Mermaid");return s(),A("div",null,[a[2]||(a[2]=n('<h1 id="ip-分片" tabindex="-1">IP 分片 <a class="header-anchor" href="#ip-分片" aria-label="Permalink to &quot;IP 分片&quot;">​</a></h1><div class="epigraph"><p>路径上各链路 MTU 不同；IPv4 允许路由器把数据报切成片，目的主机用标识与片偏移拼回。</p><footer>—— 据 Postel, RFC 791；Kurose and Ross 对分片与重组的整理</footer></div><p><a href="/cs/lpm">上一课</a>按最长前缀选出下一跳。本课不重做 TCAM 直觉。缺口是：下一跳链路能装的载荷（MTU）可能小于这份数据报。RFC 791 允许中间节点分片；重组只在最终目的。本课不把 ICMP 的「需要分片」当已讲完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>以太网载荷常 1500 字节，中间某跳更小（隧道、PPPoE）。若路由器只丢，端到端必须自己发现。IPv4：片头复制大部分 IP 头，用 Identification 标明同属一份，Flags 与 Fragment Offset 标明位置与是否最后一片。任一片丢则整份失败。缺口是<strong>把一份数据报适配多段 MTU</strong>，不是新的路由算法。</p><p><span class="marginnote">DF 置位则不分片，发 ICMP 要求缩小。PMTU 发现把分片从路由器推回源主机。IPv6 禁止中间分片，对照在后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>超 MTU 且允许分片：切开载荷，每片独立转发、独立 LPM。目的用标识+源+目的+协议把片放进重组缓冲，到齐或超时。片乱序到达是正常的；重叠片是异常，实现必须定义如何拒收，本课不把重叠当攻击教程。</p>',8)),(s(),o(i,null,{default:E(()=>[B(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DG%5B%22%E4%B8%80%E4%BB%BD%20IP%20%E6%95%B0%E6%8D%AE%E6%8A%A5%22%5D%20--%3E%20MTU%5B%22%E6%9F%90%E8%B7%B3%20MTU%20%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20MTU%20--%3E%20FRAG%5B%22%E5%88%87%E6%88%90%E7%89%87%E5%B9%B6%E8%BD%AC%E5%8F%91%22%5D%0A%20%20FRAG%20--%3E%20DST%5B%22%E7%9B%AE%E7%9A%84%E9%87%8D%E7%BB%84%22%5D%0A%20%20DST%20--%3E%20UP%5B%22%E4%BA%A4%E7%BB%99%E4%BC%A0%E8%BE%93%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("分片让网络层在异构链路上仍交出「主机到主机」的数据报语义，代价是放大丢包：丢一片等于丢全部。校验：IPv4 头校验每片重算；载荷校验在传输层，重组后才有意义——又一次"),t("a",{href:"/cs/layering-e2e"},"端到端"),e("。防火墙与 NAT 必须跟踪片或要求第一片带端口，否则后课 NAPT 会卡住。")],-1)),(s(),o(i,null,{default:E(()=>[B(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%224000%20%E5%AD%97%E8%8A%82%E6%95%B0%E6%8D%AE%E6%8A%A5%2C%20ID%3D77%22%5D%20--%3E%20F1%5B%22%E7%89%871%3A%20offset%3D0%2C%20MF%3D1%22%5D%0A%20%20D%20--%3E%20F2%5B%22%E7%89%872%3A%20offset%3D1480%2C%20MF%3D1%22%5D%0A%20%20D%20--%3E%20F3%5B%22%E7%89%873%3A%20offset%3D2960%2C%20MF%3D0%22%5D%0A%20%20F1%20--%3E%20R%7B%22%E9%87%8D%E7%BB%84%E7%BC%93%E5%86%B2%3A%20%E7%94%A8%20ID%2B%E6%BA%90%2B%E7%9B%AE%E7%9A%84%2B%E5%8D%8F%E8%AE%AE%20%E9%85%8D%E5%AF%B9%22%7D%0A%20%20F2%20--%3E%20R%0A%20%20F3%20--%3E%20R%0A%20%20R%20--%3E%20OK%5B%22%E4%B8%89%E7%89%87%E5%88%B0%E9%BD%90%3A%20%E6%8C%89%E5%81%8F%E7%A7%BB%E6%8B%BC%E5%9B%9E%22%5D%0A%20%20LOSS%5B%22%E4%BB%BB%E4%BD%95%E4%B8%80%E7%89%87%E4%B8%A2%E5%A4%B1%22%5D%20--%3E%20DROP%5B%22%E8%B6%85%E6%97%B6%E6%94%BE%E5%BC%83%3A%20%E6%95%B4%E4%BB%BD%E4%BD%9C%E5%BA%9F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">数字实例：4000 字节数据报过 MTU=1500 的链路，每片要留 20 字节 IP 头，所以每片载荷最多 1480 字节：切成 \\(1480+1480+1040\\) 三片，片偏移分别记 \\(0\\)、\\(1480\\)、\\(2960\\)（单位是 8 字节块的话再除 8），前两片 MF 置 1，末片 MF 置 0。</span></p><p><span class="marginnote">直觉类比：分片像把一份 10 页的传真按 A5 纸张张重发，每页都编上「第几份传真 + 第几页 + 是不是最后一页」，收件人凑齐再装订成原件；任何一页寄丢，整份传真作废重传。</span></p><p><span class="marginnote">为什么重要：丢包率会被平方放大——若每片丢失率 \\(p\\)，\\(n\\) 片整体成功率约 \\((1-p)^n\\)。1000 字节包切成 2 片时，\\(p=1\\%\\) 的链路上成功率从 99% 跌到约 98%，这正是现代做法宁可源端发小包、用 PMTU 发现避开中间分片的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入全部 IPv6 分片头字段，不把巨型帧当默认 MTU。也不讨论应用层自己切 UDP 载荷与 IP 分片的重复。ICMP 如何回报不可达与超时，下一课。</p><p>后课默认：IPv4 可以在路上切开，只在目的拼回。控制报文与错误回报，下一课 ICMP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RFC 791：中间可分片，目的重组；一片丢失则整份失败。</li><li>DF 把问题推回源站。</li><li>错误与探测用 ICMP，下一课。</li><li>出处：RFC 791；Kurose and Ross。</li></ul>',8))])}const C=l(d,[["render",D]]);export{F as __pageData,C as default};
